<section class="panel"><div class="panel-header"><div><h2>Pedidos da loja</h2><p><?= count($pedidos) ?> pedido(s) encontrado(s).</p></div><a class="btn btn-primary" href="index.php?entidade=pedidos&acao=novo">+ Registrar pedido</a></div><form class="filters" method="get"><input type="hidden" name="entidade" value="pedidos"><div class="field grow"><label for="buscar">Pesquisar</label><input id="buscar" name="buscar" value="<?= e($busca) ?>" placeholder="Número, cliente ou e-mail"></div><div class="field"><label for="status">Status</label><select id="status" name="status"><option value="">Todos</option><?php foreach (['recebido'=>'Recebido','em_preparacao'=>'Em preparação','enviado'=>'Enviado','concluido'=>'Concluído','cancelado'=>'Cancelado'] as $key=>$label): ?><option value="<?= $key ?>" <?= $status===$key?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></div><button class="btn btn-secondary">Filtrar</button></form>
<?php if (!$pedidos): ?><div class="empty-state">Nenhum pedido encontrado.</div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Pedido</th><th>Cliente</th><th>Data</th><th>Itens</th><th>Pagamento</th><th>Total</th><th>Status</th><th>Ações</th></tr></thead><tbody><?php foreach ($pedidos as $p): ?><tr><td><strong>#<?= (int)$p['id'] ?></strong></td><td class="text-left"><?= e($p['nome_cliente']) ?><br><small class="muted"><?= e($p['email_cliente']) ?></small></td><td><?= e(date('d/m/Y H:i',strtotime($p['created_at']))) ?></td><td><?= (int)$p['unidades'] ?></td><td><?= e(strtoupper($p['forma_pagamento'])) ?></td><td>R$ <?= number_format((float)$p['total'],2,',','.') ?></td><td><?= e(['recebido'=>'Recebido','em_preparacao'=>'Em preparação','enviado'=>'Enviado','concluido'=>'Concluído','cancelado'=>'Cancelado'][$p['status']]??$p['status']) ?></td><td><a class="btn btn-small btn-secondary" href="index.php?entidade=pedidos&acao=detalhe&id=<?= (int)$p['id'] ?>">Detalhes</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
